import{z as d,x as n,o as e,c as A,q as o,j as s,D as E,d as t,s as l,S as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"系统调用作为边界","description":"","frontmatter":{"title":"系统调用作为边界","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syscall-as-boundary.md","filePath":"cs/syscall-as-boundary.md","lastUpdated":1791413859000}'),i={name:"cs/syscall-as-boundary.md"};function c(p,a,C,_,h,m){const r=n("Mermaid");return e(),A("div",null,[a[2]||(a[2]=o('<h1 id="系统调用作为边界" tabindex="-1">系统调用作为边界 <a class="header-anchor" href="#系统调用作为边界" aria-label="Permalink to &quot;系统调用作为边界&quot;">​</a></h1><div class="epigraph"><p>用户代码不能直接操作内核对象；它把编号与参数放进约定位置，陷入内核，由内核决定是否执行并返回状态。</p><footer>—— 据 Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/dynamic-link-preview">动态链接直觉</a>把库代码映进同一地址空间。本课不重讲 GOT，也不从操作系统调度另起。缺口是：<code>malloc</code>、<code>read</code>、打开文件看起来像函数，<strong>有些必须请求内核，因为页表、文件与进程不是用户态能改的对象</strong>。系统调用是本栏里第一道硬件协助的保护边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户态与内核态用处理器模式位分开。普通 <code>call</code> 进共享库仍是用户态；真正改内核状态要走陷阱：系统调用指令或旧的中断门，带上调用号与参数。缺口因此不是「Linux 有哪些 syscall」，而是<strong>失败与成功都经过这条边界</strong>：返回值编码错误，参数里的用户指针要由内核在核内再验证。错误码课的模式在这里变成硬件强制——你无法「忽略模式位」去写磁盘。</p><p>C 库包装把陷阱藏进普通函数。本课要看见包装后面的陷入，否则后课进程、文件、网络都会被误认成「又一个库」。ISO C 的 <code>fopen</code> 是标准库；底下是否系统调用由实现决定，但在有内核的主机上，最终会碰到本课这条边界。</p><p><span class="marginnote">「陷入」就是 CPU 把控制权连同特权级一起交给内核的那条指令：从那一刻起，执行的代码、用的栈、能碰的页表全换成内核的。它不是一次跳转，是一次「换人」。</span></p><h3 id="系统调用不是普通间接调用" tabindex="-1">系统调用不是普通间接调用 <a class="header-anchor" href="#系统调用不是普通间接调用" aria-label="Permalink to &quot;系统调用不是普通间接调用&quot;">​</a></h3><p>虚表与 PLT 仍在同一特权级里跳转。系统调用切换特权、改页表可见性、让内核用自己的栈。返回时可能伴随信号、被调度到别的线程——那些是后课。本课只钉：控制与数据穿过特权边界，参数按另一套 ABI（系统调用约定）放置，不必与用户函数的调用约定相同。</p><p><span class="marginnote">CSAPP 用陷入、异常与系统调用来解释用户/内核交接。ISO C 把宿主环境里的输入输出定义为库；本栏把「必须特权」的那一层单独点名，以免组成课之前完全看不见内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户把调用号与参数写入寄存器（或栈，视 ABI），执行陷入指令。内核根据编号分派，检查指针是否指向用户可访问页，执行或拒绝，把状态写回约定寄存器，再返回用户态。C 库把负错误码转成 <code>-1</code> 加 <code>errno</code>。阻塞的调用在核内等待，用户栈帧仍按调用约定活着——从源码看像一次很慢的函数。</p>',12)),(e(),s(B,null,{default:E(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E5%BA%93%E5%8C%85%E8%A3%85%22%5D%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%EF%BC%9A%E8%B0%83%E7%94%A8%E5%8F%B7%E4%B8%8E%E5%8F%82%E6%95%B0%22%5D%0A%20%20TRAP%20--%3E%20KERN%5B%22%E5%86%85%E6%A0%B8%E6%A3%80%E6%9F%A5%E5%B9%B6%E6%89%A7%E8%A1%8C%22%5D%0A%20%20KERN%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%8A%B6%E6%80%81%E5%88%B0%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A%20%20RET%20--%3E%20ERR%5B%22%E5%BA%93%E6%94%B9%E5%86%99%E6%88%90%E8%BF%94%E5%9B%9E%E5%80%BC%E4%B8%8E%20errno%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>不是每个库函数都陷入：纯计算的 <code>strlen</code> 不必。边界在「是否需要内核对象」，不在函数名字是否像系统词。</p><p>不是所有失败都来自内核：库可以在陷入前因参数非法直接返回。调用方仍只看见错误码。追踪真正陷入要用专门的跟踪器看调用号，调试器在包装函数下断只能看见用户态。这与第一课「不要把编译当黑盒」同类：包装是又一层翻译。后课地址空间解释用户指针：内核按用户页表去拷贝，失败返回 <code>EFAULT</code>，这是合法错误，不是 UB——用户程序传坏指针给系统调用，通常得到错误码而不是被标准宣布无语义。语言 UB 与内核错误要分开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>特权分开让崩溃的用户指针不能任意改内核；内核仍必须自己写对检查，否则恶意参数可以让核去解引用坏地址。这是封装在硬件上的对应：表示（页表、打开文件表）用户看不见完整布局，只能通过编号过的操作入口修改。后课组成会从门电路解释模式位如何挡住普通访存；本课只要程序员模型：想做被禁止的事，必须请求。</p><p>包装函数可以在陷入前做用户态缓冲（stdio），于是一次 <code>fprintf</code> 不一定对应一次 <code>write</code>。契约因此有两层：C 库的后置，与内核调用的后置。短写、<code>EINTR</code>、非阻塞返回是内核层的部分成功，库可能再循环，也可能暴露给调用方。本课只要程序员能指出「特权在哪一层切换」。后课地址空间会说明为何内核必须检查用户指针：那份地址只在用户地图上有意义，内核若直接解引用，用的是另一张页表。封装在硬件上的对应，就是这张检查。</p>',5)),(e(),s(B,null,{default:E(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%A8%8B%E5%BA%8F%E8%B0%83%E7%94%A8%20fprintf%22%5D%20--%3E%20BUF%5B%22stdio%20%E7%94%A8%E6%88%B7%E6%80%81%E7%BC%93%E5%86%B2%EF%BC%9A%E5%85%88%E6%8B%BC%E8%BF%9B%204KB%20%E5%9D%97%22%5D%0A%20%20BUF%20--%3E%7C%22%E6%9C%AA%E6%BB%A1%22%7C%20HOLD%5B%22%E4%B8%8D%E9%99%B7%E5%85%A5%EF%BC%9A%E5%BA%93%E5%B1%82%E7%9B%B4%E6%8E%A5%E8%BF%94%E5%9B%9E%22%5D%0A%20%20BUF%20--%3E%7C%22%E7%BC%93%E5%86%B2%E6%BB%A1%E6%88%96%20fflush%22%7C%20W%5B%22%E6%89%A7%E8%A1%8C%20write%EF%BC%9A%E9%99%B7%E5%85%A5%E5%86%85%E6%A0%B8%22%5D%0A%20%20W%20--%3E%20CK%5B%22%E5%86%85%E6%A0%B8%E9%AA%8C%E8%AF%81%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%E6%8C%87%E9%92%88%22%5D%0A%20%20CK%20--%3E%7C%22%E5%85%A8%E9%83%A8%E5%86%99%E5%AE%8C%22%7C%20OK%5B%22%E8%BF%94%E5%9B%9E%E5%86%99%E5%85%A5%E5%AD%97%E8%8A%82%E6%95%B0%22%5D%0A%20%20CK%20--%3E%7C%22%E7%9F%AD%E5%86%99%20%2F%20EINTR%22%7C%20PART%5B%22%E5%BA%93%E5%B1%82%E5%BE%AA%E7%8E%AF%E9%87%8D%E8%AF%95%E6%88%96%E4%B8%8A%E6%8A%A5%E8%B0%83%E7%94%A8%E6%96%B9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">数字实例：printf 一个 10 字节的字符串，若缓冲里已攒了 4000 字节，这次只拼进去、不陷入；攒满 4096 才发一次 write。连打 10 次 printf 可能只换来 1 次陷入——这就是两层契约的直观账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲调度器、不讲具体调用号表、不把微内核 IPC 展开。下一课<a href="/cs/process-addrspace-tour">进程地址空间一览</a>画出用户指针合法的那张地图。后课默认：改内核对象要陷入；C 库包装不是特权本身；系统调用约定可以不同于函数 ABI。</p><p><span class="marginnote">常见误区：看到函数名像系统词（open、read）就断定必陷入，看到「库函数」就以为纯用户态。判断特权只看一件事：这次操作要不要改只有内核能改的对象——与名字无关。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统调用用陷入穿过用户/内核边界，编号与参数走专用约定。</li><li>库函数可能包装陷阱，也可能纯用户态；特权不由名字决定。</li><li>用户指针由内核再验证；错误回到返回值与 <code>errno</code>。</li><li>下一课画出这些用户指针所在的地址空间。</li><li>出处：CSAPP 异常控制流；ISO C 宿主库与本栏的特权分层。</li></ul>',6))])}const T=d(i,[["render",c]]);export{u as __pageData,T as default};
